import React, { useState } from "react";
import AppShell from "@/components/layout/AppShell";
import CommandPalette from "@/components/layout/CommandPalette";
import { useDashboardData } from "@/hooks/useDashboardData";
import { Link } from "react-router-dom";
import {
  CalendarBlank, UsersThree, CurrencyInr, Heart,
  Sparkle, CaretDown,
  MagnifyingGlass,
} from "@phosphor-icons/react";
import NotificationDropdown from "@/components/notifications/NotificationDropdown";
import {
  LineChart, Line, ResponsiveContainer, XAxis, YAxis, Tooltip, CartesianGrid, Area, AreaChart,
} from "recharts";
import DashboardStatCard from "@/components/glass/DashboardStatCard";
import StatCardsRow from "@/components/glass/StatCardsRow";
import DashboardDateTime from "@/components/glass/DashboardDateTime";
import GlassCard from "@/components/glass/GlassCard";
import { useAuth } from "@/lib/auth";
import { useHospitalProfile } from "@/hooks/useHospitalProfile";
import { cn } from "@/lib/utils";

const formatRupee = (n) => `₹ ${Number(n || 0).toLocaleString("en-IN")}`;

const formatApptTime = (iso) => {
  if (!iso) return "—";
  return new Date(iso).toLocaleTimeString("en-IN", { hour: "2-digit", minute: "2-digit", hour12: true });
};

const AVATAR_GRADIENTS = [
  "from-sky-300 to-blue-400",
  "from-violet-300 to-purple-400",
  "from-rose-300 to-pink-400",
];

const Dashboard = () => {
  const { user } = useAuth();
  const { hospitalName } = useHospitalProfile();
  const { overview: data, loading } = useDashboardData();

  const [paletteOpen, setPaletteOpen] = useState(false);

  const displayName = user?.name || "Dr. Ananya Sharma";
  const firstName = displayName.includes("Dr.") ? displayName : `Dr. ${displayName.split(" ")[0]}`;

  if (loading) {
    return (
      <AppShell variant="dashboard">
        <div className="dashboard-page h-full px-3 sm:px-4 lg:px-5 pt-1 animate-pulse flex flex-col gap-4 overflow-hidden">
          <div className="grid grid-cols-1 sm:grid-cols-4 gap-2.5">
            <div className="sm:col-span-2 h-12 bg-white/25 rounded-2xl" />
            <div className="hidden sm:block sm:col-span-2 h-10 bg-white/25 rounded-2xl" />
          </div>
          <div className="grid grid-cols-2 xl:grid-cols-4 gap-2.5">
            {[1, 2, 3, 4].map((i) => <div key={i} className="h-[88px] bg-white/25 rounded-2xl" />)}
          </div>
        </div>
      </AppShell>
    );
  }

  if (!data) {
    return (
      <AppShell variant="dashboard">
        <div className="h-full flex items-center justify-center text-slate-500 text-sm">Dashboard data could not be loaded.</div>
      </AppShell>
    );
  }

  const appointmentsWeek = Array.isArray(data.appointments_week) ? data.appointments_week : [];
  const revenueWeek = Array.isArray(data.revenue_week) ? data.revenue_week : [];
  const revenueChartMax = Math.max(1, ...revenueWeek.map((d) => Number(d.amount) || 0));
  const upcoming = Array.isArray(data.upcoming_appointments) ? data.upcoming_appointments : [];

  const apptTrendPct = data.appointments_today_change_pct ?? 12;
  const patientTrendPct = data.new_patients_change_pct ?? 8;
  const revenueTrendPct = data.revenue_mtd_change_pct ?? 15;

  return (
    <AppShell variant="dashboard">
      <div className="dashboard-page h-full px-3 sm:px-4 lg:px-5 pb-20 lg:pb-0 flex flex-col gap-2 sm:gap-3 overflow-y-auto lg:overflow-hidden">
        <header className="shrink-0 flex items-center justify-between gap-2 sm:justify-end">
          <DashboardDateTime className="flex sm:hidden text-[10px] px-2 py-1" />
          <DashboardDateTime className="hidden sm:flex" />
        </header>

        <div className="shrink-0 flex flex-col gap-3 sm:gap-4">
          <div className="grid grid-cols-1 sm:grid-cols-4 gap-2.5 items-center">
            <div className="sm:col-span-2 min-w-0">
              <h1
                className="font-heading text-xl lg:text-[1.375rem] font-bold tracking-tight text-slate-800 leading-tight truncate"
                data-testid="page-title"
              >
                Good morning, {firstName} 👋
              </h1>
              <p className="text-xs text-slate-500 mt-0.5 truncate">
                Here&apos;s what&apos;s happening at {hospitalName} today.
              </p>
            </div>

            <div className="col-span-2 hidden sm:flex items-center justify-end gap-2 min-h-8">
              <button
                data-testid="open-command-palette"
                onClick={() => setPaletteOpen(true)}
                className="flex-1 max-w-[calc(100%-2.75rem)] ml-[25%] glass-input hover:bg-white/50 transition-colors flex items-center gap-2 px-3 py-1.5 text-xs text-slate-400"
              >
                <MagnifyingGlass weight="regular" className="w-3.5 h-3.5 shrink-0" />
                <span className="flex-1 text-left truncate">Search patients, appointments...</span>
                <kbd className="font-mono text-[10px] bg-white/55 px-1.5 py-0.5 rounded hidden lg:inline">⌘K</kbd>
              </button>
              <NotificationDropdown className="p-1.5" iconClassName="w-4 h-4 text-indigo-700" />
            </div>
          </div>

          <div className="flex sm:hidden items-center gap-2">
            <button
              data-testid="open-command-palette-mobile"
              onClick={() => setPaletteOpen(true)}
              className="flex-1 glass-input hover:bg-white/50 transition-colors flex items-center gap-2 px-3 py-2 text-xs text-slate-400"
            >
              <MagnifyingGlass weight="regular" className="w-3.5 h-3.5 shrink-0" />
              <span className="flex-1 text-left truncate">Search patients, appointments...</span>
            </button>
            <NotificationDropdown className="p-2" iconClassName="w-4 h-4 text-indigo-700" />
          </div>

          {/* Stat cards — aligned row */}
          <StatCardsRow columns={4}>
            <DashboardStatCard
              testId="stat-appointments"
              icon={CalendarBlank}
              label="Today's Appointments"
              value={data.appointments_today ?? 32}
              trend={`↑ ${Math.abs(apptTrendPct)}%`}
              trendLabel="vs yesterday"
              iconBg="bg-blue-100"
              iconColor="text-blue-500"
              href="/appointments?date=today"
            />
            <DashboardStatCard
              testId="stat-new-inquiries"
              icon={UsersThree}
              label="New Patients"
              value={data.new_inquiries_today ?? 18}
              trend={`↑ ${Math.abs(patientTrendPct)}%`}
              trendLabel="vs yesterday"
              iconBg="bg-emerald-100"
              iconColor="text-emerald-500"
              href="/patients?status=new_inquiry"
            />
            <DashboardStatCard
              testId="stat-revenue"
              icon={CurrencyInr}
              label="Revenue (MTD)"
              value={formatRupee(data.revenue_mtd ?? 1872500)}
              trend={`↑ ${Math.abs(revenueTrendPct)}%`}
              trendLabel="vs last month"
              iconBg="bg-orange-100"
              iconColor="text-amber-500"
            />
            <DashboardStatCard
              testId="stat-care-score"
              icon={Heart}
              label="Care Score"
              value={`${data.care_score ?? 4.8}/5`}
              trend={`↑ ${data.care_score_change ?? 0.3}`}
              trendLabel="vs last month"
              iconBg="bg-pink-100"
              iconColor="text-pink-500"
            />
          </StatCardsRow>
        </div>

        <div className="flex-1 min-h-0">
        <div className="dashboard-main-grid h-full">
          <GlassCard variant="dashboard" padding={false} className="dashboard-cell-top-left px-3 pt-3 flex flex-col">
            <div className="flex items-center justify-between gap-2 shrink-0 mb-1">
              <div className="flex items-center gap-3 min-w-0">
                <h3 className="font-heading text-sm font-bold text-slate-800 shrink-0">Appointments Overview</h3>
                <div className="hidden md:flex items-center gap-2.5 text-[10px] text-slate-500">
                  <span className="flex items-center gap-1">
                    <span className="w-1.5 h-1.5 rounded-full bg-indigo-600" />Scheduled
                  </span>
                  <span className="flex items-center gap-1">
                    <span className="w-1.5 h-1.5 rounded-full bg-emerald-500" />Completed
                  </span>
                </div>
              </div>
              <button
                type="button"
                className="flex items-center gap-0.5 text-[10px] px-2 py-0.5 rounded-full bg-white/40 border border-white/55 text-slate-600 font-medium shrink-0"
              >
                This Week <CaretDown weight="bold" className="w-2.5 h-2.5" />
              </button>
            </div>
            <div className="flex-1 min-h-[50px]">
              <ResponsiveContainer width="100%" height="100%">
                <LineChart data={appointmentsWeek} margin={{ top: 4, right: 8, left: -16, bottom: 0 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="rgba(148,163,184,0.1)" vertical={false} />
                  <XAxis dataKey="label" tick={{ fontSize: 10, fill: "#94A3B8" }} axisLine={false} tickLine={false} dy={6} />
                  <YAxis tick={{ fontSize: 10, fill: "#94A3B8" }} axisLine={false} tickLine={false} width={28} />
                  <Tooltip contentStyle={{ fontSize: 11, borderRadius: 10 }} />
                  <Line type="monotone" dataKey="scheduled" stroke="#4F46E5" strokeWidth={2} dot={false} />
                  <Line type="monotone" dataKey="completed" stroke="#10B981" strokeWidth={2} dot={false} />
                </LineChart>
              </ResponsiveContainer>
            </div>
          </GlassCard>

          <GlassCard variant="dashboard" padding={false} className="dashboard-cell-top-right px-3 pt-3 flex flex-col">
            <div className="flex items-center justify-between mb-2 shrink-0">
              <h3 className="font-heading text-sm font-bold text-slate-800">Upcoming Appointments</h3>
              <Link to="/appointments" className="text-[10px] font-medium text-indigo-500 hover:underline">View all</Link>
            </div>
            <div className="flex-1 min-h-[50px] overflow-hidden">
              {upcoming.length === 0 && (
                <p className="text-[11px] text-slate-400 text-center py-4">No upcoming appointments</p>
              )}
              {upcoming.slice(0, 3).map((appt, idx) => {
                const isConfirmed = appt.status === "confirmed" || appt.status === "scheduled";
                return (
                  <div key={appt.id} className={cn("flex items-center gap-2 py-2", idx > 0 && "border-t border-white/35")}>
                    <div className="w-12 shrink-0 text-right">
                      <p className="text-[11px] font-semibold text-slate-800 leading-tight">{formatApptTime(appt.scheduled_at)}</p>
                      <p className="text-[9px] text-slate-400">{appt.duration_minutes || 30} min</p>
                    </div>
                    <div className={cn(
                      "w-7 h-7 rounded-full flex items-center justify-center text-white text-[10px] font-semibold shrink-0 bg-gradient-to-br ring-1 ring-white/60",
                      AVATAR_GRADIENTS[idx % AVATAR_GRADIENTS.length],
                    )}>
                      {appt.patient_name?.[0]?.toUpperCase() || "P"}
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className="text-[11px] font-semibold text-slate-800 truncate">{appt.patient_name}</p>
                      <p className="text-[10px] text-slate-500 truncate">{appt.appointment_type || "Consultation"}</p>
                    </div>
                    <span className={cn(
                      "text-[9px] px-1.5 py-0.5 rounded-full font-semibold shrink-0",
                      isConfirmed ? "bg-emerald-100 text-emerald-700" : "bg-orange-100 text-amber-700",
                    )}>
                      {isConfirmed ? "Confirmed" : "Pending"}
                    </span>
                  </div>
                );
              })}
            </div>
          </GlassCard>

          <GlassCard variant="dashboard" padding={false} className="dashboard-cell-bottom-left p-3 flex flex-col h-full min-h-0 overflow-hidden">
            <div className="dashboard-revenue-inner flex items-center gap-3 sm:gap-4 h-full min-h-0">
              <div className="shrink-0 flex flex-col justify-center max-w-[42%] sm:max-w-none">
                <h3 className="font-heading text-sm font-bold text-slate-800 mb-0.5">Revenue Overview</h3>
                <p className="text-[10px] text-slate-400 leading-tight">Total Revenue (MTD)</p>
                <p className="font-heading text-base sm:text-lg font-bold text-slate-800 leading-none mt-0.5">
                  {formatRupee(data.revenue_mtd ?? 1872500)}
                </p>
                <p className="text-[10px] mt-0.5 leading-tight">
                  <span className="font-semibold text-emerald-500">↑ {Math.abs(revenueTrendPct)}%</span>
                  <span className="text-slate-400 ml-1">vs last month</span>
                </p>
              </div>
              <div className="dashboard-revenue-chart">
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={revenueWeek} margin={{ top: 4, right: 4, left: 0, bottom: 0 }}>
                    <defs>
                      <linearGradient id="revGrad" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#8B5CF6" stopOpacity={0.35} />
                        <stop offset="100%" stopColor="#8B5CF6" stopOpacity={0.04} />
                      </linearGradient>
                    </defs>
                    <YAxis hide domain={[0, revenueChartMax]} />
                    <Area type="monotone" dataKey="amount" stroke="#8B5CF6" strokeWidth={1.5} fill="url(#revGrad)" dot={false} />
                  </AreaChart>
                </ResponsiveContainer>
              </div>
            </div>
          </GlassCard>

          <GlassCard variant="dashboard" padding={false} className="dashboard-cell-bottom-right p-3 flex flex-col justify-center" id="ai-insights">
            <div className="flex items-start gap-2.5">
              <div className="w-8 h-8 rounded-xl bg-violet-100 flex items-center justify-center shrink-0">
                <Sparkle weight="fill" className="w-4 h-4 text-violet-600" />
              </div>
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-1.5 mb-0.5">
                  <h3 className="font-heading text-xs font-bold text-slate-800">CareFlow AI Insights</h3>
                  <span className="text-[8px] uppercase px-1 py-0.5 rounded bg-violet-500 text-white font-bold">New</span>
                </div>
                <p className="text-[11px] font-semibold text-slate-800">High no-show rate on Tuesdays</p>
                <p className="text-[10px] text-slate-500 leading-snug line-clamp-2 mt-0.5">
                  Consider WhatsApp reminders 1 day before appointments.
                </p>
                <button
                  type="button"
                  className="mt-2 text-[10px] font-semibold px-3 py-1 rounded-full bg-white/50 border border-white/60 text-violet-600"
                >
                  View Insight
                </button>
              </div>
            </div>
          </GlassCard>
        </div>
        </div>
      </div>

      <CommandPalette open={paletteOpen} setOpen={setPaletteOpen} />
    </AppShell>
  );
};

export default Dashboard;
