import React from "react";
import RequirePermission from "@/components/RequirePermission";
import SettingsLayout from "@/components/settings/SettingsLayout";
import SettingsNav from "@/components/settings/SettingsNav";
import GlassCard from "@/components/glass/GlassCard";
import NotificationPreferencesContent from "@/components/notifications/NotificationPreferencesContent";
import { PERMISSIONS } from "@/lib/permissions";
import { Bell } from "@phosphor-icons/react";

const NotificationsPage = () => (
  <RequirePermission permission={PERMISSIONS.SettingsView}>
    <SettingsLayout sidebar={<SettingsNav />}>
      <div className="flex-1 min-w-0 min-h-0 flex flex-col overflow-hidden">
        <GlassCard
          padding={false}
          className="flex-1 min-h-0 overflow-hidden flex flex-col w-full max-w-4xl"
        >
          <div className="shrink-0 p-4 sm:p-6 pb-4">
            <div className="flex items-center gap-2 mb-4">
              <Bell className="w-5 h-5 text-[#4338CA]" />
              <h2 className="font-heading text-lg font-semibold text-[#022C22]">Notifications</h2>
            </div>
          </div>
          <div className="flex-1 min-h-0 overflow-hidden px-4 sm:px-6 pb-6 flex flex-col">
            <NotificationPreferencesContent />
          </div>
        </GlassCard>
      </div>
    </SettingsLayout>
  </RequirePermission>
);

export default NotificationsPage;
