import React, { useEffect, useMemo, useState } from "react";
import AppShell from "@/components/layout/AppShell";
import PageContent from "@/components/glass/PageContent";
import GlassCard from "@/components/glass/GlassCard";
import { api, formatPhone } from "@/lib/api";
import { Warning, ChatCircleDots, CalendarBlank, ListChecks, Clock } from "@phosphor-icons/react";
import { Link } from "react-router-dom";

const Section = ({ icon: Icon, title, subtitle, items, render, color, empty }) => (
  <GlassCard padding={false} className="overflow-hidden flex flex-col min-h-0">
    <div className="px-3 py-2 border-b border-white/40 flex items-center gap-2 shrink-0">
      <Icon weight="regular" className={`w-4 h-4 ${color}`} />
      <div className="flex-1 min-w-0">
        <h3 className="font-heading text-ui-sm font-semibold text-[#022C22]">{title}</h3>
        <p className="text-ui-caption text-text-secondary">{subtitle}</p>
      </div>
      <span className="text-ui-caption font-mono text-text-muted bg-white/50 px-2 py-0.5 rounded-lg">{items.length}</span>
    </div>
    <div className="divide-y divide-white/30 flex-1 min-h-0 overflow-y-auto scrollbar-thin">
      {items.length === 0 && (
        <div className="py-8 text-center text-ui-caption text-text-muted">{empty}</div>
      )}
      {items.map((it, idx) => (
        <div key={idx} className="px-3 py-2.5 hover:bg-white/40 transition-colors">{render(it)}</div>
      ))}
    </div>
  </GlassCard>
);

const MissedRevenue = () => {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    api.get("/dashboard/missed-revenue")
      .then((r) => setData(r.data))
      .catch(() => setData(null))
      .finally(() => setLoading(false));
  }, []);

  const totalItems = useMemo(() => {
    if (!data) return 0;
    return (
      (data.unanswered_inquiries?.length || 0)
      + (data.missed_appointments?.length || 0)
      + (data.lost_followups?.length || 0)
      + (data.inactive_patients?.length || 0)
    );
  }, [data]);

  const minutesSince = (iso) => {
    const ms = Date.now() - new Date(iso).getTime();
    const mins = Math.round(ms / 60000);
    if (mins < 60) return `${mins} min ago`;
    if (mins < 1440) return `${Math.round(mins / 60)} h ago`;
    return `${Math.round(mins / 1440)} d ago`;
  };

  return (
    <AppShell
      title="Analytics"
      subtitle="Missed revenue & operational accountability"
      hideHeaderSearch
      hideNotifications
      hideHospitalBadge
      showDate={false}
      scrollable={false}
      compactFooter
      wide
    >
      <PageContent wide fill flush className="flex flex-col min-h-0 gap-1.5 pb-1">
        {loading ? (
          <GlassCard className="text-center py-10 text-ui-sm text-text-muted">Loading analytics…</GlassCard>
        ) : !data ? (
          <GlassCard className="text-center py-10 text-ui-sm text-text-muted">Unable to load analytics</GlassCard>
        ) : (
          <>
            <GlassCard className="shrink-0 border-amber-200/60 bg-amber-50/40">
              <div className="flex items-start gap-3">
                <div className="w-10 h-10 rounded-xl bg-amber-100 text-amber-700 flex items-center justify-center shrink-0">
                  <Warning weight="fill" className="w-5 h-5" />
                </div>
                <div className="flex-1 min-w-0">
                  <div className="text-ui-caption uppercase tracking-[0.08em] text-amber-800/80 font-semibold mb-0.5">
                    Accountability items
                  </div>
                  <div className="font-heading text-2xl sm:text-3xl font-semibold tracking-tight text-amber-900">
                    {totalItems}
                  </div>
                  <p className="text-ui-sm text-amber-900/90 mt-1.5">
                    Each item represents potential lost patient intake. Aim to keep these at zero through the day.
                  </p>
                </div>
              </div>
            </GlassCard>

            <div className="flex-1 min-h-0 overflow-y-auto scrollbar-thin">
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-1.5 sm:gap-2">
                <Section
                  icon={ChatCircleDots} color="text-red-700"
                  title="Unanswered Inquiries"
                  subtitle="No staff reply for over 15 minutes"
                  empty="All caught up!"
                  items={data.unanswered_inquiries || []}
                  render={(c) => (
                    <Link to="/inbox" className="block">
                      <div className="flex items-center justify-between gap-2">
                        <div className="min-w-0">
                          <div className="text-ui-sm text-[#022C22] font-medium truncate">{c.name || c.wa_phone}</div>
                          <div className="text-ui-caption text-text-muted line-clamp-1">{c.last_message_preview}</div>
                        </div>
                        <div className="text-ui-caption text-red-700 font-mono shrink-0">
                          {minutesSince(c.awaiting_reply_since)}
                        </div>
                      </div>
                    </Link>
                  )}
                />

                <Section
                  icon={CalendarBlank} color="text-orange-700"
                  title="Missed Appointments"
                  subtitle="Patient did not arrive (no-show)"
                  empty="No missed appointments"
                  items={data.missed_appointments || []}
                  render={(a) => (
                    <div className="flex items-center justify-between gap-2">
                      <div className="min-w-0">
                        <div className="text-ui-sm text-[#022C22] font-medium truncate">{a.patient_name}</div>
                        <div className="text-ui-caption text-text-muted truncate">{a.doctor_name} · {a.department}</div>
                      </div>
                      <div className="text-ui-caption text-text-muted shrink-0">
                        {new Date(a.scheduled_at).toLocaleString()}
                      </div>
                    </div>
                  )}
                />

                <Section
                  icon={ListChecks} color="text-amber-700"
                  title="Overdue Follow-ups"
                  subtitle="Tasks past their due date"
                  empty="No overdue tasks"
                  items={data.lost_followups || []}
                  render={(t) => (
                    <Link to="/tasks" className="block">
                      <div className="flex items-center justify-between gap-2">
                        <div className="min-w-0">
                          <div className="text-ui-sm text-[#022C22] font-medium truncate">{t.title}</div>
                          <div className="text-ui-caption text-text-muted truncate">{t.patient_name || "—"} · {t.type?.replace(/_/g, " ")}</div>
                        </div>
                        <div className="text-ui-caption text-amber-700 shrink-0">
                          {t.due_at ? `due ${minutesSince(t.due_at)}` : ""}
                        </div>
                      </div>
                    </Link>
                  )}
                />

                <Section
                  icon={Clock} color="text-purple-700"
                  title="Inactive Patients"
                  subtitle="No contact in 90+ days · re-engage"
                  empty="All patients recently engaged"
                  items={data.inactive_patients || []}
                  render={(p) => (
                    <Link to={`/patients/${p.id}`} className="block">
                      <div className="flex items-center justify-between gap-2">
                        <div className="min-w-0">
                          <div className="text-ui-sm text-[#022C22] font-medium truncate">{p.name}</div>
                          <div className="text-ui-caption text-text-muted truncate">{formatPhone(p.phone)} · {p.department || "—"}</div>
                        </div>
                        <div className="text-ui-caption text-purple-700 shrink-0">
                          {p.last_contact_at ? minutesSince(p.last_contact_at) : "never"}
                        </div>
                      </div>
                    </Link>
                  )}
                />
              </div>
            </div>
          </>
        )}
      </PageContent>
    </AppShell>
  );
};

export default MissedRevenue;
